import{_ as o,r as s,o as i,c as r,e,a as c,s as p}from"./chunks/framework.CXcwiNg-.js";const b=JSON.parse('{"title":"Database Configuration - October CMS - 3.x","titleTemplate":false,"description":"Learn how to configure the database layer.","frontmatter":{"subtitle":"Learn how to configure the database layer."},"headers":[{"level":2,"title":"SQLite Configuration","slug":"sqlite-configuration","link":"#sqlite-configuration","children":[]},{"level":2,"title":"Read / Write Connections","slug":"read-write-connections","link":"#read-write-connections","children":[]},{"level":2,"title":"Index Lengths Using MySQL / MariaDB","slug":"index-lengths-using-mysql-mariadb","link":"#index-lengths-using-mysql-mariadb","children":[]}],"relativePath":"3.x/setup/database-config.md","filePath":"3.x/setup/database-config.md"}'),l={name:"3.x/setup/database-config.md"};function d(g,n,u,h,f,k){const a=s("pre-heading"),t=s("post-heading");return i(),r("div",null,[e(a),n[0]||(n[0]=c("h1",null,"Database Configuration",-1)),e(t),n[1]||(n[1]=p(`<p>The database configuration for your application is located in the <code>config/database.php</code> file. In this file you may define all of your database connections, as well as specify which connection should be used by default. Examples for all of the supported database systems are provided in this file.</p><h2 id="sqlite-configuration"><a href="#sqlite-configuration" class="header-anchor">#</a> SQLite Configuration</h2><p>SQLite databases use a single file on your filesystem. To create a new SQLite database, use the <code>touch</code> command.</p><div class="language-bash extra-class"><pre class="language-bash"><code><span class="token function">touch</span> storage/database.sqlite
</code></pre></div><p>After this you can configure your environment variables to use the database by placing the absolute path in the <code>DB_DATABASE</code> variable.</p><div class="language-text extra-class"><pre class="language-text"><code>DB_CONNECTION=sqlite
DB_DATABASE=/absolute/path/to/database.sqlite
</code></pre></div><h2 id="read-write-connections"><a href="#read-write-connections" class="header-anchor">#</a> Read / Write Connections</h2><p>Sometimes you may wish to use one database connection for SELECT statements, and another for INSERT, UPDATE, and DELETE statements. It is easy to specify which connection is used whether you are using raw queries, the query builder or a model.</p><p>To see how read / write connections should be configured, let&#39;s look at this example:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token string single-quoted-string">&#39;mysql&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;read&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;host&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;192.168.1.1&#39;</span><span class="token punctuation">,</span>
    <span class="token punctuation">]</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;write&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;host&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;196.168.1.2&#39;</span>
    <span class="token punctuation">]</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;driver&#39;</span>    <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;mysql&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;database&#39;</span>  <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;database&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;username&#39;</span>  <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;root&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;password&#39;</span>  <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;charset&#39;</span>   <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;utf8&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;collation&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;utf8_unicode_ci&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;prefix&#39;</span>    <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;&#39;</span><span class="token punctuation">,</span>
<span class="token punctuation">]</span><span class="token punctuation">,</span>
</code></pre></div><p>Note that two keys have been added to the configuration array: <code>read</code> and <code>write</code>. Both of these keys have array values containing a single key: <code>host</code>. The rest of the database options for the <code>read</code> and <code>write</code> connections will be merged from the main <code>mysql</code> array.</p><p>We only need to place items in the <code>read</code> and <code>write</code> arrays if we wish to override the values in the main array. So, in this case, <code>192.168.1.1</code> will be used as the &quot;read&quot; connection, while <code>192.168.1.2</code> will be used as the &quot;write&quot; connection. The database credentials, prefix, character set, and all other options in the main <code>mysql</code> array will be shared across both connections.</p><p><a id="oc-index-lengths-using-mysql-mariadb"></a></p><h2 id="index-lengths-using-mysql-mariadb"><a href="#index-lengths-using-mysql-mariadb" class="header-anchor">#</a> Index Lengths Using MySQL / MariaDB</h2><p>By default, October CMS uses a <code>utf8mb4</code> character set. If running a version of MySQL older than v5.7.7 or MariaDB older than v10.2.2, you&#39;ll need to manually configure the default string length generated by migrations in order for MySQL to create indexes for them. To configure the default string length, add the following to your <strong>config/database.php</strong> configuration file under the key <code>connections.mysql</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token string single-quoted-string">&#39;mysql&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
    <span class="token comment">// ...</span>
    <span class="token string single-quoted-string">&#39;varcharmax&#39;</span> <span class="token operator">=&gt;</span> <span class="token number">191</span><span class="token punctuation">,</span>
<span class="token punctuation">]</span><span class="token punctuation">,</span>
</code></pre></div>`,16))])}const y=o(l,[["render",d]]);export{b as __pageData,y as default};
